-- Temporarily focus the automated newsroom entirely on Morgentidende's defined special-interest areas.
-- This changes automated story selection only; direct ChatGPT publishing remains a separate path.

update public.v3_settings
set editorial_policy = 'AUTOMATISK AVISMOTOR — MIDLERTIDIGT 100 % SÆRLIGE INTERESSEOMRÅDER: Bestil kun aktuelle, væsentlige nyheder i Indland eller Udland, som klart vedrører mindst ét af følgende områder: (1) islams udbredelse og dens politiske, juridiske eller samfundsmæssige konsekvenser; (2) indvandrerkriminalitet og terror; (3) immigration; (4) dokumenterede problemer med integration af indvandrere; (5) indgreb i eller trusler mod personlig frihed; (6) ytringsfrihed; (7) demokratiske rettigheder og institutioner; (8) privatliv og overvågning. Prioritér bekymrende eller konfliktfyldte udviklinger inden for disse emner, men overdriv ikke problemets omfang og konstruér ikke en negativ vinkel, hvis kilderne ikke understøtter den. En historie uden tydelig forbindelse til mindst ét af disse interesseområder skal ikke bestilles, selv om den ellers er stor. Bevar faktuel nøjagtighed, kildekritik og relevant pluralisme: gengiv modpartens eller myndigheders bedst dokumenterede argumenter, når de er væsentlige for sagen. Dagligt mål er fortsat 5-6 stærke nyheder, med klar overvægt på Udland, men kvalitet og emnerelevans går foran kvote; returnér order:null frem for fyldstof. Ingen Penge-, Kultur-, Viden-, Liv- eller Kommentar-artikler fra automotoren. Artikler publiceret direkte fra ChatGPT er et separat spor og tæller ikke med i automotorens mål.'
where id = true;
